class Solution:
    def maxPathIntersectionSum(self, grid):
        g = [list(r) for r in grid]
        if len(g) > len(g[0]):
            g = [list(r) for r in zip(*g)]
        m, n = len(g), len(g[0])
        NEG = -(1 << 29)
        f = [[0] * m for _ in range(m)]
        S = [0] * (m + 1)
        for r in range(m):
            S[r + 1] = S[r] + g[r][0]
        for b in range(m):
            for e in range(b + 1):
                f[b][e] = S[b + 1] - S[e]
        T = [[0] * m for _ in range(m)]
        F1 = [[0] * m for _ in range(m)]
        F2 = [[0] * m for _ in range(m)]
        F3 = [[0] * m for _ in range(m)]
        F4 = [[NEG] * m for _ in range(m)]
        Ha = [[NEG] * m for _ in range(m)]
        C = [[NEG] * m for _ in range(m)]
        D = [[NEG] * m for _ in range(m)]
        for c in range(1, n):
            S = [0] * (m + 1)
            for r in range(m):
                S[r + 1] = S[r] + g[r][c]
            for a in range(m):
                for d in range(m):
                    T[a][d] = f[a][d] - S[a]
            for a in range(m):
                F1[a][m - 1] = T[a][m - 1]
                for d in range(m - 2, -1, -1):
                    F1[a][d] = max(T[a][d], F1[a][d + 1])
            for e in range(m - 2, -1, -1):
                for b in range(m):
                    if F1[e + 1][b] > F1[e][b]:
                        F1[e][b] = F1[e + 1][b]
            for tbl in (F2, F3):
                for a in range(m):
                    tbl[a][:] = f[a]
                for a in range(m):
                    for d in range(m - 2, -1, -1):
                        if tbl[a][d + 1] > tbl[a][d]:
                            tbl[a][d] = tbl[a][d + 1]
                for d in range(m):
                    for a in range(1, m):
                        if tbl[a - 1][d] > tbl[a][d]:
                            tbl[a][d] = tbl[a - 1][d]
            for b in range(m):
                sm = NEG
                for e in range(b - 1, -1, -1):
                    if f[b][e] > sm:
                        sm = f[b][e]
                    F4[b][e] = sm
                if b:
                    for e in range(m):
                        if F4[b - 1][e] > F4[b][e]:
                            F4[b][e] = F4[b - 1][e]
            for e in range(m):
                Ha[m - 1][e] = NEG
            for b in range(m - 2, -1, -1):
                for e in range(m - 1, -1, -1):
                    v = f[b + 1][e]
                    if b + 2 < m and Ha[b + 1][e] > v:
                        v = Ha[b + 1][e]
                    if e + 1 < m and Ha[b][e + 1] > v:
                        v = Ha[b][e + 1]
                    Ha[b][e] = v
            for e in range(m):
                best = NEG
                for a in range(e + 1):
                    v = f[a][e] + S[e + 1]
                    if v > best:
                        best = v
                for b in range(e, m):
                    v = best
                    if b > e and C[e][b - 1] > v:
                        v = C[e][b - 1]
                    C[e][b] = v
            for e in range(m - 1, -1, -1):
                run = NEG
                for b in range(e, m):
                    v = f[e][b] + S[b + 1] - S[e]
                    if v > run:
                        run = v
                    best = run
                    if e + 1 < m and D[e + 1][b] > best:
                        best = D[e + 1][b]
                    D[e][b] = best
            nf = [[NEG] * m for _ in range(m)]
            for b in range(m):
                sb = S[b + 1]
                for e in range(m):
                    if e > b:
                        nf[b][e] = F3[b][e]
                        continue
                    best = max(Ha[b][e], F4[b][e])
                    best = max(best, F1[e][b] + sb)
                    best = max(best, F2[e][b] + sb - S[e])
                    best = max(best, C[e][b] - S[e])
                    best = max(best, D[e][b])
                    nf[b][e] = best
            f = nf
        return f[m - 1][0]

