class Solution {
public:
    int maxPathIntersectionSum(vector<vector<int>>& grid) {
        vector<vector<int>> g = grid;
        if (g.size() > g[0].size()) {
            vector<vector<int>> t(g[0].size(), vector<int>(g.size()));
            for (int i = 0; i < (int)g.size(); i++)
                for (int j = 0; j < (int)g[0].size(); j++) t[j][i] = g[i][j];
            g.swap(t);
        }
        int m = g.size(), n = g[0].size();
        const int NEG = INT_MIN / 2;
        vector<vector<int>> f(m, vector<int>(m, 0)), nf(m, vector<int>(m)),
            T(m, vector<int>(m)), F1(m, vector<int>(m)), F2(m, vector<int>(m)),
            F3(m, vector<int>(m)), F4(m, vector<int>(m)), Ha(m, vector<int>(m)),
            C(m, vector<int>(m)), D(m, vector<int>(m));
        vector<long long> S(m + 1, 0);
        for (int r = 0; r < m; r++) S[r + 1] = S[r] + g[r][0];
        for (int b = 0; b < m; b++)
            for (int e = 0; e <= b; e++) f[b][e] = S[b + 1] - S[e];
        for (int c = 1; c < n; c++) {
            fill(S.begin(), S.end(), 0LL);
            for (int r = 0; r < m; r++) S[r + 1] = S[r] + g[r][c];
            for (int a = 0; a < m; a++)
                for (int d = 0; d < m; d++) T[a][d] = f[a][d] - S[a];
            for (int a = 0; a < m; a++) {
                F1[a][m - 1] = T[a][m - 1];
                for (int d = m - 2; d >= 0; d--) F1[a][d] = max(T[a][d], F1[a][d + 1]);
            }
            for (int e = m - 2; e >= 0; e--)
                for (int b = 0; b < m; b++) F1[e][b] = max(F1[e][b], F1[e + 1][b]);
            for (int pass = 0; pass < 2; pass++) {
                auto& tbl = pass ? F3 : F2;
                tbl = f;
                for (int a = 0; a < m; a++)
                    for (int d = m - 2; d >= 0; d--) tbl[a][d] = max(tbl[a][d], tbl[a][d + 1]);
                for (int d = 0; d < m; d++)
                    for (int a = 1; a < m; a++) tbl[a][d] = max(tbl[a][d], tbl[a - 1][d]);
            }
            for (int b = 0; b < m; b++) {
                int sm = NEG;
                for (int e = 0; e < m; e++) F4[b][e] = NEG;
                for (int e = b - 1; e >= 0; e--) { sm = max(sm, f[b][e]); F4[b][e] = sm; }
                if (b) for (int e = 0; e < m; e++) F4[b][e] = max(F4[b][e], F4[b - 1][e]);
            }
            for (int e = 0; e < m; e++) Ha[m - 1][e] = NEG;
            for (int b = m - 2; b >= 0; b--)
                for (int e = m - 1; e >= 0; e--) {
                    int v = f[b + 1][e];
                    if (b + 2 < m) v = max(v, Ha[b + 1][e]);
                    if (e + 1 < m) v = max(v, Ha[b][e + 1]);
                    Ha[b][e] = v;
                }
            for (int e = 0; e < m; e++) {
                int best = NEG;
                for (int a = 0; a <= e; a++) best = max(best, f[a][e] + (int)S[e + 1]);
                for (int b = e; b < m; b++) {
                    int v = best;
                    if (b > e) v = max(v, C[e][b - 1]);
                    C[e][b] = v;
                }
            }
            for (int e = m - 1; e >= 0; e--) {
                int run = NEG;
                for (int b = e; b < m; b++) {
                    run = max(run, f[e][b] + (int)S[b + 1] - (int)S[e]);
                    int v = run;
                    if (e + 1 < m) v = max(v, D[e + 1][b]);
                    D[e][b] = v;
                }
            }
            for (int b = 0; b < m; b++) {
                int sb = S[b + 1];
                for (int e = 0; e < m; e++) {
                    if (e > b) { nf[b][e] = F3[b][e]; continue; }
                    int best = max(Ha[b][e], F4[b][e]);
                    best = max(best, F1[e][b] + sb);
                    best = max(best, F2[e][b] + sb - (int)S[e]);
                    best = max(best, C[e][b] - (int)S[e]);
                    best = max(best, D[e][b]);
                    nf[b][e] = best;
                }
            }
            f.swap(nf);
        }
        return f[m - 1][0];
    }
};

