            }
        }
        for (let e = m - 1; e >= 0; e--) {
            let run = NEG;
            for (let b = e; b < m; b++) {
                run = Math.max(run, f[e][b] + S[b + 1] - S[e]);
                let v = run;
                if (e + 1 < m) v = Math.max(v, D[e + 1][b]);
                D[e][b] = v;
            }
        }
        for (let b = 0; b < m; b++) {
            const sb = S[b + 1];
            for (let e = 0; e < m; e++) {
                if (e > b) { nf[b][e] = F3[b][e]; continue; }
                let best = Math.max(Ha[b][e], F4[b][e]);
                best = Math.max(best, F1[e][b] + sb);
                best = Math.max(best, F2[e][b] + sb - S[e]);
                best = Math.max(best, C[e][b] - S[e]);
                best = Math.max(best, D[e][b]);
                nf[b][e] = best;
            }
        }
        [f, nf] = [nf, f];
    }
    return f[m - 1][0];
};
